//! `mappings::rebin` against C's `astRebin<X>` for every pixel type it
//! exists for and every spreading scheme: 1-D, 2-D and 3-D grids, linear
//! and non-linear Mappings, linear fits, subdivision, simplified and blocked
//! inputs, kernels overlapping the output's edges, bad pixels, variances, a
//! weight limit and an input region. Each case compares the status and
//! every output value and variance, through a hash of their bit patterns,
//! with a sample of values to show where a mismatch is.
//!
//! `rebin_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/rebin_probe.c`, which documents the input data.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[allow(clippy::excessive_precision)]
#[path = "rebin_oracle/cases.rs"]
mod cases;

use ast_core::mappings::{
    DynMapping, MathMap, PermMap, RebinFlags, RebinInput, RebinOptions, RebinOutput, ShiftMap,
    Spread, UnitMap, WinMap, ZoomMap, rebin,
};
use ast_core::pixel::RebinValue;

fn mapping(name: &str) -> DynMapping {
    match name {
        "unit2" => Box::new(UnitMap::new(2)),
        "shift_half" => Box::new(ShiftMap::new(vec![0.5, -0.25])),
        "zoom2" => Box::new(ZoomMap::new(2, 1.7).unwrap()),
        "shrink2" => Box::new(ZoomMap::new(2, 0.45).unwrap()),
        "perm" => Box::new(PermMap::new(&[2, 1], &[2, 1], &[]).unwrap()),
        "nonlin2" => Box::new(
            MathMap::new(
                2,
                2,
                &["p=a+0.02*a*b-0.3", "q=b-0.015*a*a+0.2"],
                &["a=p", "b=q"],
            )
            .unwrap(),
        ),
        "cubic1" => Box::new(MathMap::new(1, 1, &["p=0.001*a*a*a+0.5*a"], &["a=p"]).unwrap()),
        "win3" => Box::new(
            WinMap::from_corners(
                &[0.0, 0.0, 0.0],
                &[1.0, 1.0, 1.0],
                &[0.3, -0.2, 0.1],
                &[1.1, 0.7, 1.4],
            )
            .unwrap(),
        ),
        "nonlin3" => Box::new(
            MathMap::new(
                3,
                3,
                &["p=a+0.05*b*c", "q=b-0.03*a*a", "r=0.9*c+0.1*a"],
                &["a=p", "b=q", "c=r"],
            )
            .unwrap(),
        ),
        "noforward" => Box::new(MathMap::new(2, 2, &["p", "q"], &["a=p", "b=q"]).unwrap()),
        _ => panic!("no Mapping {name}"),
    }
}

fn spread(name: &str) -> Spread {
    match name {
        "nearest" => Spread::Nearest,
        "linear" => Spread::Linear,
        "sinc" => Spread::Sinc,
        "sincsinc" => Spread::SincSinc,
        "sinccos" => Spread::SincCos,
        "sincgauss" => Spread::SincGauss,
        "gauss" => Spread::Gauss,
        "somb" => Spread::Somb,
        "sombcos" => Spread::SombCos,
        _ => panic!("no scheme {name}"),
    }
}

fn npix(l: &[i64], u: &[i64]) -> usize {
    l.iter().zip(u).map(|(l, u)| (u - l + 1) as usize).product()
}

/// Run one case for pixel type `T`, returning (status, hash, samples).
fn run<T: RebinValue>(c: &cases::Case) -> (i32, u64, Vec<f64>) {
    let &(
        _,
        map,
        _,
        _,
        lbnd_in,
        ubnd_in,
        lbnd_out,
        ubnd_out,
        lbnd,
        ubnd,
        scheme,
        use_bad,
        use_var,
        var_arrays,
        params,
        tol,
        maxpix,
        wlim,
        ..,
    ) = c;
    let nin = npix(lbnd_in, ubnd_in);
    let nout = npix(lbnd_out, ubnd_out);
    let (mut data, mut var) = (Vec::with_capacity(nin), Vec::with_capacity(nin));
    for k in 0..nin as i64 {
        let (mut d, mut v) = if T::FLOATING {
            (
                T::from_f64(((7 * k) % 97) as f64 * 0.37 - 10.0),
                T::from_f64(((3 * k) % 11) as f64 * 0.5 + 0.25),
            )
        } else {
            let ds = if T::SIGNED { 11 } else { 0 };
            (
                T::from_f64(((7 * k) % 23 - ds) as f64),
                T::from_f64(((3 * k) % 11) as f64),
            )
        };
        if use_bad && k % 17 == 3 {
            d = T::from_f64(120.0);
        }
        if use_bad && k % 19 == 5 {
            v = T::from_f64(120.0);
        }
        data.push(d);
        var.push(v);
    }
    let mut out = vec![T::from_f64(77.0); nout];
    let mut out_var = vec![T::from_f64(77.0); nout];
    let m = mapping(map);
    let result = rebin(
        m.as_ref(),
        &RebinInput {
            lbnd: lbnd_in,
            ubnd: ubnd_in,
            region_lbnd: lbnd,
            region_ubnd: ubnd,
            data: &data,
            var: var_arrays.then_some(&var[..]),
        },
        &mut RebinOutput {
            lbnd: lbnd_out,
            ubnd: ubnd_out,
            data: &mut out,
            var: var_arrays.then_some(&mut out_var[..]),
        },
        &RebinOptions {
            spread: spread(scheme),
            params: &params,
            flags: RebinFlags { use_bad, use_var },
            tol,
            maxpix,
            wlim,
        },
        T::from_f64(120.0),
    );
    let status = match result {
        Ok(()) => 0,
        Err(e) => e.code() as i32,
    };
    let mut hash: u64 = 14695981039346656037;
    for k in 0..nout {
        hash = (hash ^ out[k].to_f64().to_bits()).wrapping_mul(1099511628211);
        if var_arrays {
            hash = (hash ^ out_var[k].to_f64().to_bits()).wrapping_mul(1099511628211);
        }
    }
    let samples = out.iter().step_by(97).map(|v| v.to_f64()).collect();
    (status, hash, samples)
}

#[test]
fn rebinning_matches_c() {
    let mut failures = Vec::new();
    for c in cases::CASES {
        let (name, ty, want_status, want_hash, want_samples) = (c.0, c.2, c.18, c.19, c.20);
        let (status, hash, samples) = match ty {
            "D" => run::<f64>(c),
            "F" => run::<f32>(c),
            "I" => run::<i32>(c),
            "B" => run::<i8>(c),
            "UB" => run::<u8>(c),
            _ => panic!("no type {ty}"),
        };
        let same_samples = samples.len() == want_samples.len()
            && samples
                .iter()
                .zip(want_samples)
                .all(|(a, b)| a.to_bits() == b.to_bits());
        if status != want_status || hash != want_hash || !same_samples {
            failures.push(format!(
                "{name} {ty}: status {status} want {want_status}; hash {}; samples\n  got  \
                 {samples:?}\n  want {want_samples:?}",
                if hash == want_hash { "same" } else { "differs" }
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} cases differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn errors_match_c() {
    let input: Vec<f64> = (0..100).map(f64::from).collect();
    let l2: &[i64] = &[1, 1];
    let u2: &[i64] = &[10, 10];
    let bad: &[i64] = &[11, 1];
    let run = |map: &str,
               lbnd_in: &[i64],
               lbnd_out: &[i64],
               ubnd_out: &[i64],
               region: (&[i64], &[i64]),
               tol: f64| {
        // C's arrays are whole whatever the bounds say.
        let n = match npix(lbnd_out, ubnd_out) {
            0 => 100,
            n => n,
        };
        let mut out = vec![7.0_f64; n];
        let status = match rebin(
            mapping(map).as_ref(),
            &RebinInput {
                lbnd: lbnd_in,
                ubnd: &u2[..lbnd_in.len()],
                region_lbnd: region.0,
                region_ubnd: region.1,
                data: &input[..match npix(lbnd_in, &u2[..lbnd_in.len()]) {
                    0 => 100,
                    n => n.min(100),
                }],
                var: None,
            },
            &mut RebinOutput {
                lbnd: lbnd_out,
                ubnd: ubnd_out,
                data: &mut out,
                var: None,
            },
            &RebinOptions {
                spread: Spread::Linear,
                params: &[],
                flags: RebinFlags::default(),
                tol,
                maxpix: 50,
                wlim: 0.0,
            },
            -1.0,
        ) {
            Ok(()) => 0,
            Err(e) => e.code() as i32,
        };
        (status, [out[0], out[1]])
    };
    let l3: &[i64] = &[1, 1, 1];
    let u3: &[i64] = &[10, 10, 10];
    let got = [
        run("unit2", &l2[..1], l2, u2, (&l2[..1], &u2[..1]), 0.0),
        run("unit2", l2, l3, u3, (l2, u2), 0.0),
        run("unit2", bad, l2, u2, (bad, u2), 0.0),
        run("unit2", l2, bad, u2, (l2, u2), 0.0),
        run("unit2", l2, l2, u2, (&[0, 1], u2), 0.0),
        run("unit2", l2, l2, u2, (l2, &[10, 11]), 0.0),
        run("unit2", l2, l2, u2, (&[5, 1], &[4, 10]), 0.0),
        run("unit2", l2, l2, u2, (l2, u2), -1.0),
        run("noforward", l2, l2, u2, (l2, u2), 0.0),
        run("unit2", l2, l2, u2, (l2, u2), 0.0),
    ];
    assert_eq!(got, cases::ERRORS);
}

/// Parameters fewer than the scheme reads, which C cannot detect, are an
/// error.
#[test]
fn too_few_params_is_an_error() {
    let input = vec![1.0_f64; 100];
    let mut out = vec![0.0_f64; 100];
    let (l, u): (&[i64], &[i64]) = (&[1, 1], &[10, 10]);
    for (spread, params) in [
        (Spread::Sinc, &[][..]),
        (Spread::SincCos, &[2.0][..]),
        (Spread::Gauss, &[2.0][..]),
    ] {
        let e = rebin(
            &UnitMap::new(2),
            &RebinInput {
                lbnd: l,
                ubnd: u,
                region_lbnd: l,
                region_ubnd: u,
                data: &input,
                var: None,
            },
            &mut RebinOutput {
                lbnd: l,
                ubnd: u,
                data: &mut out,
                var: None,
            },
            &RebinOptions {
                spread,
                params,
                flags: RebinFlags::default(),
                tol: 0.0,
                maxpix: 50,
                wlim: 0.0,
            },
            -1.0,
        )
        .unwrap_err();
        assert_eq!(e.code(), ast_core::error::ErrorCode::Dimin, "{spread:?}");
    }
}
